    Lemma susp_fin : forall msF mo mc (r : rv) Fx mw bw ew xg ng j6 slv (q : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1017c8) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw mw bw ew xg ng j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rra r = Z_to_bv 64 0x1083e4 -> ra0 r = a0 -> ra1 r = Z_to_bv 64 q -> p <= q <= e ->
