    Lemma fin_fin : forall msF mo mc (r : rv) Fx (mw : word) (bc xc xn : Z) j6 slv (p' : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107f1c) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) ->
      uframe mc spw mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 p' -> p < p' <= e -> -2^27 < bc < 2^27 -> 0 <= xc < 2^31 -> 0 <= xn <= 1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
