    Lemma xend_fin : forall msF mo mc (r : rv) Fx (mw : word) (bc xc xn : Z) j6 slv,
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107eac) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 bc) (Z_to_bv 64 xc) (b8 xn) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 e -> p + 2 <= e -> -2^27 < bc < 2^27 -> 0 <= xc <= 2147483647 -> 0 <= xn <= 1 ->
