      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107e4c) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 bc) (Z_to_bv 64 x) (b8 xn) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra2 r = Z_to_bv 64 x -> ra1 r = Z_to_bv 64 9 ->
      ra4 r = Z_to_bv 64 2147483647 -> ra5 r = Z_to_bv 64 214748364 -> ra3 r = Z_to_bv 64 55 -> ra6 r = Z_to_bv 64 10 ->
      p + 2 <= q < e -> -2^27 < bc < 2^27 -> 0 <= x <= 2147483647 -> 0 <= xn <= 1 ->
      as_SR H POST (mkCfg msF mo).
Proof.
