    Lemma bl_loopn : forall (n : nat) (q : Z) msF mo mc (r : rv) Fx (mw : word) (c0 k b a3v : Z) j6 slv,
      (Z.to_nat (e - q) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107b70) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> ra1 r = Z_to_bv 64 c0 -> ra4 r = Z_to_bv 64 k -> ra0 r = Z_to_bv 64 b -> ra3 r = Z_to_bv 64 a3v ->
      ra5 r = Z_to_bv 64 9 -> ra6 r = Z_to_bv 64 (-2147483649) -> ra7 r = Z_to_bv 64 1 ->
      q = c0 + k + 1 -> 0 <= k -> p + 1 <= c0 -> q < e -> 1 <= b <= q - p -> a3v = b + (e - q) ->
      as_SR H POST (mkCfg msF mo).
