    (* [comment removed for export] *)
    Lemma xb_fin : forall msF mo mc (r : rv) Fx (mw mw0 : word) (c0 k : Z) j6 slv (q : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107b40) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw0 (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 c0 -> ra4 r = Z_to_bv 64 (- k) -> ra2 r = mw -> ra3 r = Z_to_bv 64 (q - e) ->
      q = c0 + k -> 0 <= k -> p + 1 <= c0 -> q < e ->
      as_SR H POST (mkCfg msF mo).
Proof.
