    Lemma x2_fin : forall msF mo mc (r : rv) Fx (mw mw0 : word) j6 slv (q : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x108198) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw0 (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> ra0 r = Z_to_bv 64 q -> ra2 r = mw -> rt2 r = Z_to_bv 64 (sh8 q) ->
      p + 1 <= q < e -> (0 <= bv_unsigned (inb q) + -48 - 10 \/ bv_unsigned (inb q) < 48) ->
      as_SR H POST (mkCfg msF mo).
