    (* [comment removed for export] *)
    Lemma jft_fin : forall msF mo mc (r : rv) Fx (mw acc : word) j6 slv (q n1 n2 j : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1088d0) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 (q + 1) -> ra5 r = Z_to_bv 64 n2 -> ra0 r = Z_to_bv 64 (q + 1 + n2 + - j) ->
      ra3 r = acc -> ra6 r = Z_to_bv 64 j ->
      q = p + n1 -> 1 <= n1 <= 15 -> 1 <= n2 <= 16 -> n1 + n2 <= 18 -> 0 <= j <= 3 -> j <= n2 -> 33 <= e - p ->
