    Lemma jfl_loop_n : forall (n : nat) (i : Z) msF mo mc (r : rv) Fx (mw acc : word) j6 slv (q n1 n2 : Z),
      (Z.to_nat (n1 + n2 - i) <= n)%nat ->
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1087e8) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> ra1 r = Z_to_bv 64 (q + 1) -> ra5 r = Z_to_bv 64 n2 -> ra2 r = Z_to_bv 64 (p + 1) ->
      ra4 r = Z_to_bv 64 i -> ra3 r = acc -> ra6 r = Z_to_bv 64 (n1 + n2 + - i) -> ra7 r = Z_to_bv 64 10 -> rt0 r = Z_to_bv 64 3 ->
      q = p + n1 -> 1 <= n1 <= 15 -> 1 <= n2 <= 16 -> n1 + n2 <= 18 -> n1 <= i -> i + 4 <= n1 + n2 -> 33 <= e - p ->
      as_SR H POST (mkCfg msF mo).
