    (* [comment removed for export] *)
    Lemma m1_fin : forall msF mo mc (r : rv) Fx (mw : word) j6 slv (q n1 : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x107d3c) fc None mc (seg_rom asegs) -> ra4 r = Z_to_bv 64 n1 ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> rs2 r = Z_to_bv 64 q -> q = p + n1 -> 1 <= n1 <= 15 -> 33 <= e - p ->
