    Lemma pul_loop : forall msF mo mc (r : rv) Fx (mw acc : word) j6 slv (k i : Z),
      as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
      as_VIS H s msF = MS (mkRr r) Fx (Z_to_bv 64 0x1085b4) fc None mc (seg_rom asegs) ->
      nst mc -> stk asegs mc lo (bv_unsigned spw) -> pinb mc p0 e inb -> pshb mc p0 e ->
      uframe mc spw mw (Z_to_bv 64 0) (Z_to_bv 64 0) (b8 0) (b8 0) j6 slv s4 s3 s2 s1 s0 ra ->
      bregs r -> ra1 r = Z_to_bv 64 (p + i) -> ra0 r = Z_to_bv 64 (p + i) -> ra3 r = acc -> ra4 r = Z_to_bv 64 k ->
      ra5 r = Z_to_bv 64 (k + - i) -> ra6 r = Z_to_bv 64 10 -> ra7 r = Z_to_bv 64 3 ->
      4 <= k <= 16 -> 0 <= i -> i + 4 <= k -> 33 <= e - p ->
      as_SR H POST (mkCfg msF mo).
Proof.
